package com.theseusoft.service;
import com.theseusoft.dto.*; import com.theseusoft.entity.*; import com.theseusoft.repository.SupportTicketRepository; import java.time.Year; import java.util.List; import org.springframework.stereotype.Service;
@Service public class SupportTicketService { private final SupportTicketRepository repository; public SupportTicketService(SupportTicketRepository repository){this.repository=repository;} public SupportTicketResponse create(SupportTicketRequest request){var entity=new SupportTicket();entity.setTicketNumber("TK-"+Year.now().getValue()+"-"+String.format("%05d",repository.count()+1));entity.setName(request.name());entity.setEmail(request.email());entity.setCompany(request.company());entity.setCategory(request.category());entity.setSubject(request.subject());entity.setMessage(request.message());return map(repository.save(entity));} public List<SupportTicketResponse> findAll(){return repository.findAll().stream().map(this::map).toList();} private SupportTicketResponse map(SupportTicket t){return new SupportTicketResponse(t.getId(),t.getTicketNumber(),t.getName(),t.getEmail(),t.getCompany(),t.getCategory(),t.getSubject(),t.getMessage(),t.getStatus(),t.getCreatedAt());} }
